import math

def find_closest_elements(numbers: list[float]) -> tuple[float, float]:
    if len(numbers) < 2:
        raise ValueError("The list must contain at least two numbers.")

    min_distance: float = math.inf
    closest_pair: tuple[float, float] = (0.0, 0.0)

    for i: int in range(len(numbers)):
        for j: int in range(i + 1, len(numbers)):
            num1: float = numbers[i]
            num2: float = numbers[j]
            distance: float = abs(num1 - num2)

            if distance < min_distance:
                min_distance = distance
                closest_pair = (min(num1, num2), max(num1, num2))

    return closest_pair

