def factorize(n: int) -> list[int]:
    factors: list[int] = []
    divisor: int = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n = n // divisor
        divisor = divisor + 1
        if divisor * divisor > n:
            if n > 1:
                factors.append(n)
                break
    return factors

